  test("proofs scenario 3", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "floor", "2.00");
    await ui.setSetting(pg_uma, "terms", "7");
    await ui.setSetting(pg_uma, "late-pct", "10.00");
    await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
    await ui.setSetting(pg_uma, "cap", "5.00");
    await ui.setSetting(pg_uma, "proof-threshold", "1.00");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "4.00", "date": "2026-03-05"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.statement(pg_uma, p_ben)).toBe(true);
    expect(await ui.hold(pg_uma, p_ada, {"from": "2026-02-10", "to": "2026-03-15"})).toBe(true);
    expect(await ui.defer(pg_uma, c_ada_0, "2026-04-20")).toBe(true);
    expect(await ui.defer(pg_uma, c_ada_0, "2026-04-16")).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.claimAction(pg_vic, c_ada_0, "settle")).toBe(false);
    await ui.refresh(pg_vic);
    expect(await ui.statement(pg_vic, p_ben)).toBe(true);
    expect(await ui.claimAction(pg_vic, c_ada_0, "settle")).toBe(false);
    const c_ada_1 = ui.must(await ui.addClaim(pg_vic, p_ada, {"amount": "99.95", "date": "2026-03-15"}));
    await ui.setToday(pg_vic, "2026-05-11");
    expect(await ui.defer(pg_vic, c_ada_0, "2026-05-21")).toBe(true);
    expect(await ui.claimAction(pg_vic, c_ada_1, "open")).toBe(true);
    expect(await ui.pasteClaims(pg_vic, "Ada,10.35,2026-03-28,")).toBe(1);
    const c_ada_2 = await ui.claimAt(pg_vic, p_ada, 2);
    await ui.refresh(pg_vic);
